{
  "name": "HP 8116A 波形发生器",
  "name_en": "HP 8116A waveform generator",
  "manufacturer": "Hewlett-Packard",
  "description": "HP 8116A 是一台最高约 50 MHz 的台式波形/函数信号发生器，可输出正弦波、三角波、方波和直流等信号，并可调节频率、幅度与直流偏置。它常用于电子电路测试、仪器联调和实验室中的激励信号产生。",
  "description_en": "The HP 8116A is a benchtop waveform/function generator with output frequencies up to about 50 MHz. It can generate sine, triangle, square, and DC signals, with adjustable frequency, amplitude, and DC offset. It is commonly used in electronics testing, instrument setup, and laboratory signal stimulation.",
  "tag_hints": [
    "function generator",
    "waveform generation",
    "up to 50 MHz",
    "sine triangle square output",
    "DC offset control",
    "electronic test stimulus"
  ],
  "actions": [
    {
      "action_name": "auto-state",
      "description": "获取设备当前状态",
      "description_en": "get the current device state"
    },
    {
      "action_name": "auto-frequency",
      "description": "获取/设置输出频率",
      "description_en": "get/set the output frequency"
    },
    {
      "action_name": "auto-shape",
      "description": "获取/设置输出波形形状",
      "description_en": "get/set the output waveform shape"
    },
    {
      "action_name": "auto-amplitude",
      "description": "获取/设置输出幅度",
      "description_en": "get/set the output amplitude"
    },
    {
      "action_name": "auto-offset",
      "description": "获取/设置直流偏置",
      "description_en": "get/set the DC offset"
    }
  ]
}

